import{_ as a,a as s,c as e,ac as t}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"Linux awk 基础命令","description":"awk 字段、条件、行号、分隔符与聚合示例","frontmatter":{"title":"Linux awk 基础命令","description":"Linux awk 基础命令","sources":[{"repository":"jekyall_blog","file":"_posts/DevOps/Linux/cmd/2023-05-08-linux_awk.md","date":"Mon May 08 2023 12:06:01 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"linux","title":"Linux","link":"/topics/linux/"}],"kind":"命令与系统观察","scope":"general","audience":"general","group":"容器与运维","summary":"awk 字段、条件、行号、分隔符与聚合示例","status":"active","related":[{"title":"Linux 基础命令","link":"/systems/linux/base/basic/basic","kind":"知识专题","scope":"general","audience":"general"},{"title":"Linux：部署受限维护任务与定时器","link":"/systems/linux/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"Linux：进程、systemd、网络与存储","link":"/systems/linux/base/intermediate/mechanisms","kind":"知识专题","scope":"general","audience":"general"},{"title":"Linux：日志轮转、软件维护与备份恢复","link":"/systems/linux/plus/practice/operations","kind":"知识专题","scope":"general","audience":"general"},{"title":"Linux：系统识别、文件路径与账号权限","link":"/systems/linux/base/basic/start","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","link":"/systems/linux/common-commands-part-07"},"next":{"text":"Linux：进程、服务与资源","link":"/systems/linux/plus/ecosystem/linux-process-general-general"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","link":"/systems/linux/common-commands-part-07"},"next":{"text":"Linux：进程、服务与资源","link":"/systems/linux/plus/ecosystem/linux-process-general-general"}},"headers":[],"relativePath":"systems/linux/plus/ecosystem/linux_awk.md","filePath":"systems/linux/plus/ecosystem/linux_awk.md"}'),l={name:"systems/linux/plus/ecosystem/linux_awk.md"};function n(p,i,r,h,k,o){return s(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="linux-awk-基础命令" tabindex="-1">Linux awk 基础命令 <a class="header-anchor" href="#linux-awk-基础命令" aria-label="Permalink to &quot;Linux awk 基础命令&quot;">​</a></h1><h2 id="awk" tabindex="-1">awk <a class="header-anchor" href="#awk" aria-label="Permalink to &quot;awk&quot;">​</a></h2><p>awk 是一种用于处理文本数据的命令行工具，它可以用来从文件或者管道中读取数据，并对其进行格式化、转换、过滤和计算等操作。下面是一个简单的 awk 命令使用指南：</p><h2 id="_1-基础语法" tabindex="-1">1. 基础语法 <a class="header-anchor" href="#_1-基础语法" aria-label="Permalink to &quot;1. 基础语法&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [options] </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;pattern { action }&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> file(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>其中，pattern 表示匹配模式，action 表示要执行的动作。如果没有指定 pattern，则默认匹配所有行。file(s) 表示输入文件名，可以指定多个文件。</p><h2 id="_2-使用变量" tabindex="-1">2. 使用变量 <a class="header-anchor" href="#_2-使用变量" aria-label="Permalink to &quot;2. 使用变量&quot;">​</a></h2><p>awk 中有一些内置变量，可以用于获取当前正在处理的行或者列的信息。例如：</p><ul><li>$0 表示整个行内容；</li><li>$1 表示第一个字段（以空格分隔）；</li><li>$NF 表示最后一个字段；</li><li>NR 表示当前行号；</li><li>NF 表示当前行的字段数。</li></ul><p>在 awk 中，可以使用这些变量来进行行或者列的处理和计算。</p><h2 id="_3-常用操作" tabindex="-1">3. 常用操作 <a class="header-anchor" href="#_3-常用操作" aria-label="Permalink to &quot;3. 常用操作&quot;">​</a></h2><p>以下是 awk 常用的操作：</p><ul><li>打印行：<code>awk &#39;{print}&#39; file.txt</code></li><li>按条件过滤行：<code>awk &#39;/pattern/ {print}&#39; file.txt</code></li><li>格式化输出：<code>awk &#39;{printf &quot;%s %s\\n&quot;, $1, $2}&#39; file.txt</code></li><li>计算行数：<code>awk &#39;END {print NR}&#39; file.txt</code></li><li>计算平均值：<code>awk &#39;{sum+=$1; count++} END {print sum/count}&#39; file.txt</code></li><li>按分隔符处理：<code>awk -F&#39;,&#39; &#39;{print $1, $NF}&#39; file.txt</code></li></ul><h2 id="_4-常用选项" tabindex="-1">4. 常用选项 <a class="header-anchor" href="#_4-常用选项" aria-label="Permalink to &quot;4. 常用选项&quot;">​</a></h2><p>以下是 awk 常用的一些选项：</p><ul><li><code>-F&lt;separator&gt;</code> 指定分隔符；</li><li><code>-v var=value</code> 定义变量；</li><li><code>-f script.awk</code> 指定脚本文件。</li></ul><p>例如，可以使用以下命令从 CSV 文件中提取第一列和最后一列：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;,&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $1, $NF}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.csv</span></span></code></pre></div><p>也可以将选项和脚本组合起来使用，例如：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;,&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> threshold=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">90</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{if ($3 &gt; threshold) print $0}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.csv</span></span></code></pre></div><p>这个命令会读取 file.csv 文件，并根据逗号分隔符解析每一行数据。然后根据变量 threshold 进行过滤，如果第三列的值大于 threshold，则输出整行数据。</p>',21)])])}const u=a(l,[["render",n]]);export{c as __pageData,u as default};
